// Bench Worker: a tenant object that runs the real Whagons Query/Reducer
// bundle through the K04 module host, with the catalog cache on or off.
import { DurableObject } from "cloudflare:workers";
// @ts-expect-error generated by bench/prepare.mjs (git-ignored)
import * as app from "./.build/app.js";
// @ts-expect-error generated by bench/prepare.mjs (git-ignored)
import functions from "./.build/functions.json";
// @ts-expect-error generated by bench/prepare.mjs (git-ignored)
import summary from "./.build/summary.json";
import { TenantStorage } from "../../storage/index";
import { ModuleRegistry, TenantModuleHost, type FunctionContract, type TenantCall } from "../src/index.js";

interface Entry { kind: "query" | "reducer" | "action"; internal?: boolean; args: unknown; result: unknown }
const manifest = functions as Record<string, Entry>;
const contracts: FunctionContract[] = Object.entries(manifest)
  .filter(([, entry]) => entry.kind !== "action")
  .map(([path, entry]) => ({ path, kind: entry.kind, internal: entry.internal === true, argsSchema: entry.args, resultSchema: entry.result }));
// Actions are not in the split bundle; keep them registered so the scheduler
// accepts them as targets, with a placeholder export.
const actions: FunctionContract[] = Object.entries(manifest)
  .filter(([, entry]) => entry.kind === "action")
  .map(([path]) => ({ path, kind: "action", argsSchema: { kind: "any" }, resultSchema: { kind: "any" }, export: "__action" }));

const json = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });

export class BenchTenant extends DurableObject {
  registry = new ModuleRegistry("whagons");
  host: TenantModuleHost | undefined;
  storage: TenantStorage | undefined;
  readonly startedLoadMs: number;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    const started = Date.now();
    this.registry.install({
      moduleId: "whagons",
      generation: (summary as { generation: number }).generation,
      artifactHash: (summary as { artifactHash: string }).artifactHash,
      functions: [...contracts, ...actions],
      exports: { ...(app as Record<string, unknown>), __action: () => null },
    });
    this.startedLoadMs = Date.now() - started;
  }

  private ensureHost(): TenantModuleHost {
    if (!this.host) {
      // S2's permission stub: owners and admins hold every permission.
      const roles = new Map(this.ctx.storage.sql.exec("SELECT id, role FROM members").toArray().map((row) => [String(row["id"]), String(row["role"])]));
      const permissions = { has: (member: string) => ["owner", "admin"].includes(roles.get(member) ?? "") };
      this.storage = new TenantStorage(this.ctx.storage);
      this.host = new TenantModuleHost({ storage: this.storage, registry: this.registry, permissions });
    }
    return this.host;
  }

  override async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const body = request.method === "POST" ? await request.json() as Record<string, unknown> : {};
    switch (url.pathname) {
      case "/provision": {
        const failures: unknown[] = [];
        let executed = 0;
        for (const statement of body["statements"] as { type: string; name: string; sql: string }[]) {
          try { this.ctx.storage.sql.exec(statement.sql); executed++; } catch (error) { failures.push({ type: statement.type, name: statement.name, error: String((error as Error).message).slice(0, 200) }); }
        }
        for (const { table, rows } of body["rows"] as { table: string; rows: Record<string, unknown>[] }[]) {
          for (const row of rows) {
            const keys = Object.keys(row);
            try {
              this.ctx.storage.sql.exec(`INSERT INTO "${table}" (${keys.map((k) => `"${k}"`).join(",")}) VALUES (${keys.map((_, i) => `?${i + 1}`).join(",")})`, ...keys.map((k) => row[k] as SqlStorageValue));
            } catch (error) { failures.push({ type: "row", name: table, error: String((error as Error).message).slice(0, 200) }); }
          }
        }
        this.host?.schemaChanged();
        return json({ executed, failures, databaseSize: this.ctx.storage.sql.databaseSize });
      }
      case "/invoke": {
        const host = this.ensureHost();
        // "Cache off" is Rust's behavior: catalogs read again in every invocation.
        if (body["cache"] === false) host.schemaChanged();
        const started = Date.now();
        const report = await host.run(body["call"] as TenantCall);
        return json({ ...report, serverMs: Date.now() - started });
      }
      case "/snapshot": {
        // Every table's rows, minus wall-clock and random columns, for the
        // cache-on / cache-off comparison.
        const volatile = new Set(["created_at", "updated_at", "available_at"]);
        const out: Record<string, string[]> = {};
        const tables = this.ctx.storage.sql.exec("SELECT name FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%' AND name <> '__miniflare_do_name' ORDER BY name").toArray();
        for (const { name } of tables) {
          const rows = this.ctx.storage.sql.exec(`SELECT * FROM "${String(name).replaceAll('"', '""')}"`).toArray();
          if (!rows.length) continue;
          out[String(name)] = rows.map((row) => JSON.stringify(Object.fromEntries(Object.entries(row)
            .filter(([column]) => !volatile.has(column))
            .map(([column, v]) => [column, String(name) === "_gonvex_action_outbox" && column === "id" && row["action_path"] === "_gonvex.scheduler.enqueue" ? "<random>" : v instanceof ArrayBuffer ? `blob:${v.byteLength}` : v])))).sort();
        }
        return json(out);
      }
      case "/meta":
        return json({ loadMs: this.startedLoadMs, functions: this.registry.activeGeneration?.engine.functions.size, exports: Object.keys(app).length, unresolved: this.registry.activeGeneration?.engine.unresolved().length });
      default:
        return json({ error: "not found" }, 404);
    }
  }
}

export default {
  fetch(request: Request, env: Env): Promise<Response> | Response {
    const url = new URL(request.url);
    if (url.pathname === "/ping") return json({ ok: true });
    return env.TENANT.getByName(url.searchParams.get("tenant") ?? "bench").fetch(request);
  },
};
